'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readStore=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const state=readStore('supply-lab-v1',{done:[],zoom:100,dark:false,last:null,positions:{}});state.positions||={};state.done||=[];
let course,current='home',searchIndex=[],tocObserver,scrollTimer,toastTimer,activeLab='eoq';
function persist(){try{localStorage.setItem('supply-lab-v1',JSON.stringify(state))}catch{}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2300)}
function applySettings(){state.zoom=Math.min(150,Math.max(80,state.zoom||100));document.documentElement.style.setProperty('--reader-size',17*state.zoom/100+'px');$('#zoomLabel').textContent=state.zoom+'%';$('#zoomOut').disabled=state.zoom<=80;$('#zoomIn').disabled=state.zoom>=150;document.body.classList.toggle('dark',state.dark);$('#themeBtn').setAttribute('aria-pressed',String(!!state.dark))}
applySettings();
$('#zoomOut').onclick=()=>{state.zoom-=10;applySettings();persist()};$('#zoomIn').onclick=()=>{state.zoom+=10;applySettings();persist()};$('#themeBtn').onclick=()=>{state.dark=!state.dark;applySettings();persist()};$('#focusBtn').onclick=()=>{const on=document.body.classList.toggle('focus');$('#focusBtn').setAttribute('aria-pressed',String(on));toast(on?'Focus mode on':'Focus mode off')};
function closeNav(){document.body.classList.remove('nav-open');$('#menuBtn').setAttribute('aria-expanded','false')}
$('#menuBtn').onclick=()=>{const on=document.body.classList.toggle('nav-open');$('#menuBtn').setAttribute('aria-expanded',String(on))};$('#scrim').onclick=closeNav;$('#topBtn').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});
$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
function updateNav(){
 $('#chapterNav').innerHTML=course.chapters.map(c=>`<a href="#${c.id}" class="${current===c.id?'active':''}" ${current===c.id?'aria-current="page"':''}><span class="chapter-number">${String(c.number).padStart(2,'0')}</span><span>${escapeHTML(shortTitle(c))}</span>${state.done.includes(c.id)?'<span class="chapter-complete" aria-label="Completed">✓</span>':''}</a>`).join('');
 $$('.main-nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===current);if(a.dataset.page===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const count=state.done.filter(id=>course.chapters.some(c=>c.id===id)).length;$('#progressLabel').textContent=count+' / 14';$('#courseProgress').value=count;
}
function shortTitle(c){return ['Customers & marketing','Supply chains & integration','Strategy & VRIN','Industrial networks · ARA','Purchasing & suppliers','The Kraljic matrix','Operations & quality','Lean, agile & leagile','Inventory & calculations','Systems & logistics','Negotiation','The connected case','Exam answers & practice','Recall & formula sheet'][c.number-1]}
function heroMap(){return `<div class="hero-map" aria-label="The connected business: customer, company, suppliers and operations"><span class="map-note">EVERY DECISION IS CONNECTED</span><div class="map-net"><svg viewBox="0 0 440 260" role="img" aria-label="Campus Tees connects customer needs, suppliers, operations and delivery"><path d="M220 70L80 130L220 208L360 130Z M220 70V208 M80 130H360" fill="none" stroke="#9aaa8a" stroke-width="1.5" stroke-dasharray="4 5"/><circle cx="220" cy="130" r="54" fill="#163e36"/><text x="220" y="126" font-size="16" font-family="Georgia" text-anchor="middle" fill="#e1f0c9">Campus Tees</text><text x="220" y="147" font-size="9" font-family="Arial" text-anchor="middle" fill="#c2d8ad">OUR RUNNING EXAMPLE</text><g font-family="Arial" font-size="10" text-anchor="middle" fill="#294b36"><rect x="165" y="15" width="110" height="42" rx="9" fill="#fff"/><text x="220" y="40">Customer needs</text><rect x="12" y="108" width="105" height="42" rx="9" fill="#d2e3c2"/><text x="65" y="133">Suppliers</text><rect x="323" y="108" width="105" height="42" rx="9" fill="#e9c4a6"/><text x="375" y="133">Operations</text><rect x="165" y="211" width="110" height="42" rx="9" fill="#fff"/><text x="220" y="236">Delivered value</text></g></svg></div><span class="map-footer">One simple business. The whole module.</span></div>`}
function renderHome(){const resume=course.chapters.find(c=>c.id===state.last)||course.chapters[0];return `<section class="hero"><div><div class="eyebrow">Your exam study companion</div><h1>Understand the<br><em>whole chain.</em></h1><p>From what customers need to how businesses deliver it. Learn the entire module through simple explanations, visual models and one connected example.</p><div class="button-row"><a class="btn primary" href="#${resume.id}">${state.last?'Continue learning':'Start learning'} <span>↗</span></a><a class="btn" href="#13-exam">Practise for the exam</a></div></div>${heroMap()}</section>${pastExamSpotlight()}<div class="metric-row"><div class="metric"><strong>14</strong><span>CONNECTED<br>CHAPTERS</span></div><div class="metric"><strong>31</strong><span>ZOOMABLE<br>DIAGRAMS</span></div><div class="metric"><strong>25</strong><span>GLOSSARY<br>ENTRIES</span></div><div class="metric"><strong>4</strong><span>INTERACTIVE<br>EXPLORERS</span></div></div><div class="section-heading"><div><h2>Start with the exam examples</h2><p>Two topics your teacher used to show the question format.</p></div><a href="#13-exam">See model answers ↗</a></div><div class="spotlight-grid"><a href="#04-networks" class="spotlight"><div class="spotlight-badge">5<small>POINTS</small></div><div><h3>The ARA network model</h3><p>Actors, resources and activities—and how they connect.</p></div><span class="arrow">↗</span></a><a href="#06-kraljic" class="spotlight"><div class="spotlight-badge">10<small>POINTS</small></div><div><h3>The Kraljic matrix</h3><p>Describe it, give examples and discuss the trade-offs.</p></div><span class="arrow">↗</span></a></div><div class="section-heading"><div><h2>Your learning path</h2><p>Read in order, or jump to the concept you need.</p></div><span class="eyebrow" style="margin:0">${course.words.toLocaleString()} words</span></div><div class="chapters-grid">${course.chapters.map(c=>`<a href="#${c.id}" class="chapter-card"><div class="card-top"><span><i class="dot"></i> CHAPTER ${String(c.number).padStart(2,'0')}</span><span>${state.done.includes(c.id)?'✓ COMPLETE':c.minutes+' MIN READ'}</span></div><h3>${escapeHTML(shortTitle(c))}</h3><p>${escapeHTML(c.summary)}</p><div class="card-bottom"><span>${c.sections.length} sections ${c.number===9?'· 3 calculators':''}</span><span>Explore ↗</span></div></a>`).join('')}</div><div class="home-bottom"><p><strong>Keep the source wording. Understand what it means.</strong><br>Exact definitions, plain-English explanations and everyday examples, with all 16 original course files and 3 past papers beside them.</p><a class="btn" href="#glossary">Open the glossary ↗</a></div>`}
function renderChapter(c){const prev=course.chapters[c.number-2],next=course.chapters[c.number];return `<div class="reader-layout"><article class="reader" id="reader"><div class="eyebrow">Chapter ${String(c.number).padStart(2,'0')} / 14</div><h1>${escapeHTML(c.title)}</h1><div class="chapter-meta"><span>${c.minutes} min read</span><span>${c.words.toLocaleString()} words</span><span>${c.sections.length} sections</span>${c.number===13?'<button id="toggleAnswers">Reveal all answers</button>':''}<a href="#sources">Source materials ↗</a></div>${c.html}<div class="chapter-actions"><button class="read-btn ${state.done.includes(c.id)?'done':''}" id="completeBtn">${state.done.includes(c.id)?'✓ Chapter completed':'Mark chapter complete'}</button><div class="prev-next">${prev?`<a href="#${prev.id}">← Previous</a>`:''}${next?`<a href="#${next.id}">Next chapter →</a>`:'<a href="#home">Back to overview →</a>'}</div></div></article><aside class="toc" aria-label="On this page"><strong>ON THIS PAGE</strong>${c.sections.map(s=>`<a href="#${c.id}/${s.id}" data-section="${s.id}">${escapeHTML(s.title)}</a>`).join('')}</aside></div>`}
function renderGlossary(){return `<div class="page-heading"><div class="eyebrow">Definitions made understandable</div><h1>The complete glossary.</h1><p>All 25 entries from Johan Larsson’s 2026 glossary. Read the original wording, then the simpler explanation and example. Clarifications flag wording that needs care.</p></div><div class="glossary-toolbar"><label for="glossaryFilter" class="sr-only">Filter glossary</label><input id="glossaryFilter" class="field" placeholder="Find an abbreviation or concept…"><span id="glossaryCount">25 entries</span></div><div class="glossary-grid">${course.glossary.map(e=>`<section class="term-card" id="${e.id}" data-term="${escapeHTML((e.term+' '+e.exact+' '+e.simple).toLowerCase())}"><h2>${escapeHTML(e.term)}</h2><span class="label">Exact glossary wording</span><blockquote>${escapeHTML(e.exact)}</blockquote><span class="label">In plain English</span><p>${escapeHTML(e.simple)}</p><span class="label">Easy example</span><p>${escapeHTML(e.example)}</p><p class="term-note">${escapeHTML(e.note)}</p></section>`).join('')}</div><p id="glossaryEmpty" class="empty-state" hidden>No entries match. Try a shorter word.</p>`}
function renderSources(){return `<div class="page-heading"><div class="eyebrow">Check the original</div><h1>Your course materials.</h1><p>All 16 original course uploads plus 3 past-exam PDFs, including the scanned readings and the glossary. Open a PDF to inspect the original diagrams, zoom and scroll through the pages.</p></div><div class="source-notice"><strong>How this study guide uses the material</strong><br>The chapters reorganise the readings by concept and connect them through examples. Block quotations identify exact source wording; the surrounding explanations and 31 redrawn study diagrams are teaching interpretations. The model answers are study examples, not official marking schemes.<details><summary>Edition and coverage notes</summary><p>${escapeHTML(course.sourceNote)}</p><p>The main reading list contains Barney (1991), Naylor, Naim & Berry (1999), Christopher (2011 excerpt), Ford & Mouzas (2013), Gadde & Håkansson (1994), Kraljic (1983) and Larsson (2020), alongside all lecture slides. Optional further-reading names on the networks slide are oriented in the recall chapter; their full works were not uploaded.</p></details><a class="btn" href="study-guide.md" download style="margin-top:15px">Download the complete text ↓</a></div>${course.sources.some(s=>s.external)?'<p class="source-notice">Original document files open in your private Study Lab. Sign in there if requested.</p>':''}<div class="source-grid">${course.sources.map((s,i)=>`<section class="source-card"><span class="type">${s.type} ${s.pages?'· '+s.pages+' PAGES':''}</span><h2>${escapeHTML(s.title)}</h2>${s.external?`<a href="${s.url}" target="_blank" rel="noopener">Open original in private Study Lab ↗</a>`:s.type==='PDF'?`<button data-source="${i}">Read and zoom original ↗</button>`:`<a href="${s.url}" download>Download original glossary ↓</a>`}</section>`).join('')}</div>`}
const labInfo={eoq:{title:'Economic order quantity',desc:'Change demand and costs. See how the quantity balances ordering and holding.',fields:[['D','Annual demand D','units/year',12000,1],['K','Cost per order K','€/order',30,.01],['h','Annual holding cost h','€/unit/year',2,.01]]},reorder:{title:'Reorder point',desc:'Quantity and timing are different decisions. Cover lead-time demand plus a buffer.',fields:[['d','Demand per working day d','units/day',40,0],['L','Lead time L','working days',5,0],['SS','Safety stock SS','units',60,0]]},breakeven:{title:'Break-even explorer',desc:'Find the output at which total contribution covers fixed cost.',fields:[['F','Fixed cost F','€',1200,0],['p','Selling price p','€/unit',15,0],['v','Variable cost v','€/unit',9,0],['q','Planned sales q','units',300,0]]}};
function calculatorHTML(type){const info=labInfo[type];return `<section class="calculator" data-calculator="${type}"><div class="calc-title"><h3>${info.title}</h3><p>${info.desc}</p></div><div class="calc-body"><form class="calc-inputs" autocomplete="off">${info.fields.map(([key,label,unit,value,min])=>`<label>${label} <span style="color:var(--muted)">(${unit})</span><input type="number" name="${key}" value="${value}" min="${min}" step="any" inputmode="decimal" required></label>`).join('')}<button type="button" class="btn calc-reset">Reset example</button></form><div class="calc-result" role="status" aria-live="polite"></div></div></section>`}
function money(n){return new Intl.NumberFormat('en',{maximumFractionDigits:2}).format(n)}
function calculate(type,v){if(Object.values(v).some(x=>!Number.isFinite(x)||x<0))return {error:'Enter a non-negative number in every field.'};if(type==='eoq'){if(!v.D||!v.K||!v.h)return {error:'Demand, order cost and holding cost must all be greater than zero for this EOQ model.'};const Q=Math.sqrt(2*v.D*v.K/v.h);return {Q,orders:v.D/Q,avg:Q/2,ordering:v.K*v.D/Q,holding:v.h*Q/2}}if(type==='reorder')return {rop:v.d*v.L+v.SS,leadDemand:v.d*v.L};if(v.p<=v.v)return {error:'No positive finite break-even point: price must exceed variable cost per unit. Each sale needs a positive contribution.'};return {be:v.F/(v.p-v.v),contribution:v.p-v.v,profit:(v.p-v.v)*v.q-v.F,revenue:v.p*v.q,cost:v.F+v.v*v.q}}
function chartSVG(type,v,r){const W=400,H=170,pad=20;let paths='',extra='';const line=(points,color)=>`<polyline points="${points.map(([x,y])=>x.toFixed(1)+','+y.toFixed(1)).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5"/>`;if(type==='eoq'){const qs=Array.from({length:60},(_,i)=>r.Q*(.25+i*1.75/59)),max=Math.max(...qs.map(q=>v.K*v.D/q+v.h*q/2));for(const [fn,color] of [[q=>v.K*v.D/q+v.h*q/2,'#163e36'],[q=>v.K*v.D/q,'#b5704b'],[q=>v.h*q/2,'#839575']])paths+=line(qs.map((q,i)=>[pad+i*(W-pad*2)/59,H-pad-fn(q)/max*(H-pad*2)]),color);extra='<text x="22" y="14" font-size="9" fill="#536449">Total · ordering · holding cost</text>'}else{const maxQ=Math.max(r.be*1.6,v.q*1.1,1),maxY=Math.max(v.F+v.v*maxQ,v.p*maxQ,1);paths=line([[pad,H-pad],[W-pad,H-pad-v.p*maxQ/maxY*(H-2*pad)]],'#163e36')+line([[pad,H-pad-v.F/maxY*(H-2*pad)],[W-pad,H-pad-(v.F+v.v*maxQ)/maxY*(H-2*pad)]],'#b5704b');extra='<text x="22" y="14" font-size="9" fill="#536449">Revenue (green) · total cost (orange)</text>'}return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${type==='eoq'?'Annual ordering and holding cost curves':'Revenue and total cost lines'}"><path d="M20 20V150H380" fill="none" stroke="#a0b299"/>${paths}${extra}</svg>`}
function mountCalculators(){ $$('.calculator[data-calculator]').forEach(el=>{const type=el.dataset.calculator,form=el.querySelector('form'),out=el.querySelector('.calc-result');const update=()=>{const v={};for(const [key] of labInfo[type].fields){const input=form.elements[key];v[key]=input.value.trim()===''?NaN:Number(input.value)}const r=calculate(type,v);if(r.error){out.innerHTML=`<p class="calc-error">${escapeHTML(r.error)}</p>`;return}if(type==='eoq')out.innerHTML=`<span class="result-label">Optimal order quantity</span><div class="result-number">${money(r.Q)} <small>units/order</small></div><p>${money(r.orders)} orders/year · ${money(r.avg)} average cycle stock</p><p>Ordering: €${money(r.ordering)}/year<br>Holding: €${money(r.holding)}/year<br><strong>Relevant total: €${money(r.ordering+r.holding)}/year</strong></p><div class="formula">Q* = √(2 × ${money(v.D)} × ${money(v.K)} / ${money(v.h)})</div>${chartSVG(type,v,r)}<p>Constant price, stable demand, complete receipts; excludes purchase cost and safety stock.</p>`;if(type==='reorder')out.innerHTML=`<span class="result-label">Trigger replenishment at</span><div class="result-number">${money(r.rop)} <small>units</small></div><p>Expected lead-time demand: ${money(r.leadDemand)} units<br>Protective buffer: ${money(v.SS)} units</p><div class="formula">ROP = ${money(v.d)} × ${money(v.L)} + ${money(v.SS)}</div><p>Use matching demand and lead-time units. This determines when, not how much, to order.</p>`;if(type==='breakeven')out.innerHTML=`<span class="result-label">Break-even quantity</span><div class="result-number">${money(r.be)} <small>units</small></div><p>Whole-unit sales needed: ${Math.ceil(r.be)}<br>Contribution: €${money(r.contribution)}/unit<br>Profit at ${money(v.q)} units: <strong>€${money(r.profit)}</strong></p><div class="formula">qBE = ${money(v.F)} / (${money(v.p)} − ${money(v.v)})</div>${chartSVG(type,v,r)}<p>Assumes constant price and variable unit cost, within the fixed-cost range.</p>`};form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',update);form.querySelector('.calc-reset').onclick=()=>{labInfo[type].fields.forEach(([k,,,value])=>form.elements[k].value=value);update()};update()}) }
function matrixHTML(){return `<div class="calculator" style="padding:27px"><div class="matrix-controls"><div class="matrix-choice"><label for="impact">Profit impact</label><select id="impact"><option value="high">High</option><option value="low">Low</option></select></div><div class="matrix-choice"><label for="risk">Supply risk</label><select id="risk"><option value="high">High</option><option value="low">Low</option></select></div></div><div class="matrix-axes"><span>↑ Higher profit impact</span><span>Higher supply risk →</span></div><div class="matrix-grid"><div class="quadrant" data-key="high-low"><h3>Leverage</h3><p>High impact · low risk<br>Competitive bidding, qualified alternatives and buying volume.</p></div><div class="quadrant" data-key="high-high"><h3>Strategic</h3><p>High impact · high risk<br>Partnership, planning and active risk management.</p></div><div class="quadrant" data-key="low-low"><h3>Routine</h3><p>Low impact · low risk<br>Rationalise and simplify purchasing administration.</p></div><div class="quadrant" data-key="low-high"><h3>Bottleneck</h3><p>Low impact · high risk<br>Protect continuity with assurance, buffers or alternatives.</p></div></div><p class="matrix-note" id="matrixExplanation" role="status" aria-live="polite"></p><p class="matrix-note">Try classifying standard office paper, commonly available high-volume blanks, a unique low-cost spare and a specialised engine. Classification depends on the buying situation and can change.</p><a class="btn" href="#06-kraljic">Read the full explanation ↗</a></div>`}
function mountMatrix(){if(!$('#impact'))return;const update=()=>{const key=$('#impact').value+'-'+$('#risk').value;$$('.quadrant').forEach(q=>q.classList.toggle('selected',q.dataset.key===key));const name=$(`.quadrant[data-key="${key}"] h3`).textContent;$('#matrixExplanation').textContent=`This combination is ${name.toLowerCase()}. Now explain why the purchase has those characteristics and which action fits. An item's price alone is not enough to classify it.`};$('#impact').onchange=update;$('#risk').onchange=update;update()}
function renderLab(){return `<div class="page-heading"><div class="eyebrow">Learn by changing the numbers</div><h1>Make the models click.</h1><p>Try the worked examples, then change one input. The formulas and explanations update with you. These are teaching models with the assumptions shown.</p></div><div class="lab-tabs" role="tablist" aria-label="Interactive models">${[['eoq','EOQ'],['reorder','Reorder point'],['breakeven','Break-even'],['kraljic','Kraljic matrix']].map(([id,title])=>`<button role="tab" aria-selected="${activeLab===id}" class="lab-tab ${activeLab===id?'active':''}" data-labtab="${id}">${title}</button>`).join('')}</div><div class="lab-shell" role="tabpanel">${activeLab==='kraljic'?matrixHTML():calculatorHTML(activeLab)}</div>`}
function go(){if(!course)return;const [page,section]=(decodeURIComponent(location.hash.slice(1))||'home').split('/');if(page===current&&page!=='past-exams'&&section&&document.getElementById(section)){document.getElementById(section).scrollIntoView();return}tocObserver?.disconnect();current=page;const c=course.chapters.find(c=>c.id===page);const main=$('#main');if(page==='home')main.innerHTML=renderHome();else if(c){main.innerHTML=renderChapter(c);state.last=c.id;persist()}else if(page==='glossary')main.innerHTML=renderGlossary();else if(page==='past-exams')main.innerHTML=renderPastExams();else if(page==='sources')main.innerHTML=renderSources();else if(page==='lab')main.innerHTML=renderLab();else{current='home';main.innerHTML=renderHome()}document.title=(c?shortTitle(c):({home:'Your study space',glossary:'Glossary',sources:'Course materials',lab:'Interactive lab','past-exams':'Past exams'}[current]||'Study space'))+' · Supply Lab';$('#breadcrumb').textContent=c?'The learning path / '+shortTitle(c):'Your course companion';updateNav();closeNav();$$('.lab-embed').forEach(el=>el.innerHTML=calculatorHTML(el.dataset.lab));mountCalculators();mountMatrix();if(page==='past-exams')mountPastExams(section);if(c){$('#completeBtn').onclick=()=>{const index=state.done.indexOf(c.id);if(index<0){state.done.push(c.id);toast('Chapter marked complete')}else{state.done.splice(index,1);toast('Chapter marked unread')}persist();updateNav();const b=$('#completeBtn');b.textContent=state.done.includes(c.id)?'✓ Chapter completed':'Mark chapter complete';b.classList.toggle('done',state.done.includes(c.id))};if($('#toggleAnswers'))$('#toggleAnswers').onclick=()=>{const answers=$$('details.answer'),open=answers.some(a=>!a.open);answers.forEach(a=>a.open=open);$('#toggleAnswers').textContent=open?'Hide all answers':'Reveal all answers'};tocObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){$$('.toc a').forEach(a=>a.classList.toggle('current',a.dataset.section===e.target.id))}}),{rootMargin:'-90px 0px -65% 0px'});$$('.reader h2').forEach(h=>tocObserver.observe(h))}if(page==='glossary')$('#glossaryFilter').oninput=e=>{const q=e.target.value.toLowerCase().trim();let n=0;$$('.term-card').forEach(el=>{el.hidden=!el.dataset.term.includes(q);if(!el.hidden)n++});$('#glossaryCount').textContent=n+' entries';$('#glossaryEmpty').hidden=n!==0};$$('[data-labtab]').forEach(b=>b.onclick=()=>{activeLab=b.dataset.labtab;go()});requestAnimationFrame(()=>{if(section&&document.getElementById(section))document.getElementById(section).scrollIntoView();else window.scrollTo({top:state.positions[current]||0,behavior:'instant'});updateReadingProgress()});if(c)main.focus({preventScroll:true})}
function updateReadingProgress(){const max=document.documentElement.scrollHeight-window.innerHeight;$('#readingProgress').style.width=course?.chapters.some(c=>c.id===current)?Math.min(100,Math.max(0,window.scrollY/Math.max(1,max)*100))+'%':'0'}
window.addEventListener('scroll',()=>{updateReadingProgress();clearTimeout(scrollTimer);const page=current;scrollTimer=setTimeout(()=>{state.positions[page]=window.scrollY;persist()},180)},{passive:true});window.addEventListener('hashchange',go);$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()};
// Global search indexes every section, including definitions and examples.
function buildSearch(){const parser=new DOMParser();for(const c of course.chapters){const doc=parser.parseFromString(c.html,'text/html');let title=c.title,id='',text=[];const flush=()=>{if(text.length)searchIndex.push({title,chapter:shortTitle(c),url:c.id+(id?'/'+id:''),text:text.join(' ')})};for(const el of doc.body.children){if(el.tagName==='H2'){flush();title=el.textContent;id=el.id;text=[]}else text.push(el.textContent)}flush()}for(const e of course.glossary)searchIndex.push({title:e.term,chapter:'Glossary',url:'glossary/'+e.id,text:e.exact+' '+e.simple+' '+e.example+' '+e.note})}
function search(){const q=$('#globalSearch').value.toLowerCase().trim();const out=$('#searchResults');if(!q){out.innerHTML='<div class="empty-state">Start with a concept: <strong>ARA</strong>, <strong>Kraljic</strong>, <strong>EOQ</strong>, <strong>VRIN</strong> or <strong>BATNA</strong>.<br>Tip: press / anywhere to search.</div>';return}const terms=q.split(/\s+/);const hits=searchIndex.map(s=>({...s,score:terms.reduce((n,t)=>n+(s.title.toLowerCase().includes(t)?8:0)+(s.text.toLowerCase().includes(t)?1:0),0)})).filter(s=>terms.every(t=>(s.title+' '+s.text).toLowerCase().includes(t))).sort((a,b)=>b.score-a.score).slice(0,35);out.innerHTML=hits.length?hits.map(s=>{const at=s.text.toLowerCase().indexOf(terms[0]);const start=Math.max(0,at-65);return `<a class="search-result" href="#${s.url}"><small>${escapeHTML(s.chapter)}</small><strong>${escapeHTML(s.title)}</strong><p>${start?'…':''}${escapeHTML(s.text.slice(start,start+195))}…</p></a>`}).join(''):'<div class="empty-state">No matches. Try a shorter term or abbreviation.</div>';out.querySelectorAll('a').forEach(a=>a.onclick=()=>$('#searchDialog').close())}
$('#searchBtn').onclick=()=>{$('#searchDialog').showModal();search();$('#globalSearch').focus()};$('#globalSearch').oninput=search;document.addEventListener('keydown',e=>{if((e.key==='/'||((e.ctrlKey||e.metaKey)&&e.key==='k'))&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();if(!$('#searchDialog').open)$('#searchBtn').click()}});
let diagramZoom=1,diagramX=0,diagramY=0,drag=null;function transformDiagram(){const im=$('#diagramImage');im.style.transform=`translate(${diagramX}px,${diagramY}px) scale(${diagramZoom})`;$('#diagramScale').textContent=Math.round(diagramZoom*100)+'%';$('#diagramMinus').disabled=diagramZoom<=.5;$('#diagramPlus').disabled=diagramZoom>=5}function zoomDiagram(delta){diagramZoom=Math.max(.5,Math.min(5,diagramZoom+delta));transformDiagram()}$('#diagramPlus').onclick=()=>zoomDiagram(.25);$('#diagramMinus').onclick=()=>zoomDiagram(-.25);$('#diagramReset').onclick=()=>{diagramZoom=1;diagramX=diagramY=0;transformDiagram()};$('#diagramStage').addEventListener('wheel',e=>{e.preventDefault();zoomDiagram(e.deltaY>0?-.1:.1)},{passive:false});$('#diagramStage').onpointerdown=e=>{drag={x:e.clientX-diagramX,y:e.clientY-diagramY};e.currentTarget.setPointerCapture(e.pointerId)};$('#diagramStage').onpointermove=e=>{if(drag){diagramX=e.clientX-drag.x;diagramY=e.clientY-drag.y;transformDiagram()}};$('#diagramStage').onpointerup=()=>drag=null;$('#diagramStage').onpointercancel=()=>drag=null;
document.addEventListener('click',e=>{const b=e.target.closest('[data-diagram]');if(b){const key=b.dataset.diagram,f=course.figures[key];$('#diagramImage').src='diagrams/'+key+'.svg';$('#diagramImage').alt=f.description;$('#diagramTitle').textContent=f.title;$('#diagramCaption').textContent=f.description;diagramZoom=1;diagramX=diagramY=0;transformDiagram();$('#diagramDialog').showModal()}const s=e.target.closest('[data-source]');if(s){const source=course.sources[Number(s.dataset.source)];$('#sourceTitle').textContent=source.title;$('#sourceFrame').src=source.url+'#toolbar=1';$('#sourceNew').href=source.url;$('#sourceDialog').showModal()}});$('#sourceDialog').addEventListener('close',()=>$('#sourceFrame').src='about:blank');
async function init(){try{const response=await fetch('course.json');if(!response.ok)throw new Error('Course request failed');course=await response.json();buildSearch();indexPastExams();go();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{})}catch(e){$('#main').innerHTML='<div class="page-heading"><h1>The course could not load.</h1><p>Check your connection and reload the page. If you opened the HTML as a local file, serve the dist folder through a local web server.</p><button class="btn" onclick="location.reload()">Reload</button></div>';console.error(e)}}
window.SupplyLab={calculate};init();
